type WelcomeProps = { name: string };

function Welcome({ name }: WelcomeProps) {
  return (
    <section className="welcome">
      <h1>Hello, {name}!</h1>
      <p>Choose a lesson to continue.</p>
    </section>
  );
}

export function App() {
  return <Welcome name="Mira" />;
}

type LessonCardProps = {
  title: string;
  durationMinutes: number;
  onOpen: () => void;
};

function LessonCard({ title, durationMinutes, onOpen }: LessonCardProps) {
  return (
    <article>
      <h2>{title}</h2>
      <p>{durationMinutes} min</p>
      <button onClick={onOpen}>Open lesson</button>
    </article>
  );
}

